select date_trunc('MONTH', p.launch_date) as launch_month, case when p.price >= 1140 then 'high' when p.price >= 480 then 'mid' else 'low' end as price_bucket, min(i.quantity) as min_quantity, max(i.quantity) as max_quantity from inventory i left outer join products p on i.product_id = p.id where p.category not in ('Electronics', 'Books', 'Sports') group by date_trunc('MONTH', p.launch_date), case when p.price >= 1140 then 'high' when p.price >= 480 then 'mid' else 'low' end order by min_quantity
